"""r1mc3.measure.tags: tag36h11 detection with sub-pixel corners in OpenCV's order, and the tag placement geometry."""

from __future__ import annotations

import math

import cv2
import numpy as np
from r1mc3.measure import detect_tags, flat_tag


def _scene(tag_ids: list[int], H_list: list[np.ndarray], size: tuple[int, int] = (640, 480)) -> np.ndarray:
    """Tags (generated by OpenCV, 8 cells + a 1-cell white quiet zone, 100 px per cell) warped into a grey image."""
    d = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_APRILTAG_36h11)
    img = np.full((size[1], size[0]), 128, np.uint8)
    for tid, H in zip(tag_ids, H_list, strict=True):
        m = cv2.aruco.generateImageMarker(d, tid, 800)
        sheet = np.full((1000, 1000), 255, np.uint8)
        sheet[100:900, 100:900] = m
        warped = cv2.warpPerspective(sheet, H, size, flags=cv2.INTER_AREA, borderValue=0)
        mask = cv2.warpPerspective(np.full_like(sheet, 255), H, size, flags=cv2.INTER_NEAREST, borderValue=0)
        img[mask > 0] = warped[mask > 0]
    return img


def _H(dst: np.ndarray) -> np.ndarray:
    # the black square's corners in the pixel-centre convention (pixels 100..899 -> edges at 99.5 / 899.5)
    src = np.array([[99.5, 99.5], [899.5, 99.5], [899.5, 899.5], [99.5, 899.5]], np.float32)
    return cv2.getPerspectiveTransform(src, dst.astype(np.float32))


def test_a_perspective_tag_is_found_with_subpixel_corners_in_opencv_order() -> None:
    dst = np.array([[200.3, 150.7], [330.2, 160.1], [320.9, 270.4], [190.6, 255.8]])
    img = _scene([7], [_H(dst)])
    found = detect_tags(img)
    assert list(found) == [7]
    err = np.linalg.norm(found[7].corners_px - dst, axis=1)
    assert err.max() < 0.15, err  # the AprilTag edge refinement (+ its 0.5 px convention shift)
    assert 110 < found[7].edge_px < 140
    for ref in ("none", "subpix"):  # the alternatives: 0.7-1.4 px here
        other = detect_tags(img, refine=ref)
        assert np.linalg.norm(other[7].corners_px - dst, axis=1).max() > 3 * err.max()


def test_a_repeated_id_is_dropped_and_an_id_filter_keeps_only_the_plan() -> None:
    a = np.array([[50, 50], [150, 50], [150, 150], [50, 150]], float)
    img = _scene([3, 3, 5], [_H(a), _H(a + np.array([250, 0])), _H(a + np.array([0, 220]))])
    assert set(detect_tags(img)) == {5}  # 3 twice = ambiguous
    assert detect_tags(img, ids=[9]) == {}


def test_flat_tag_frame_and_corner_order() -> None:
    t = flat_tag(4, 0.10, 0.30, -0.20, 0.0)
    c = t.corners_entity()
    # marker up = +x (away from a viewer at -x), marker right = -y; corners TL, TR, BR, BL
    assert np.allclose(c[0], [0.35, -0.15, 0.0]) and np.allclose(c[1], [0.35, -0.25, 0.0])
    assert np.allclose(c[2], [0.25, -0.25, 0.0]) and np.allclose(c[3], [0.25, -0.15, 0.0])
    assert np.allclose(t.T_entity_tag[:3, 2], [0, 0, 1])
    t90 = flat_tag(4, 0.10, 0.0, 0.0, up_yaw_deg=90.0)
    assert np.allclose(t90.T_entity_tag[:3, 1], [math.cos(math.pi / 2), 1.0, 0.0], atol=1e-12)  # up along +y
